{
  "name": "@lidtop/opencode-gh-pr-status",
  "version": "0.5.0",
  "description": "See the GitHub pull requests waiting on you in the OpenCode sidebar",
  "license": "MIT",
  "author": "ZackarySantana",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ZackarySantana/opcode.git",
    "directory": "plugins/gh-pr-status"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "github"
  ],
  "engines": {
    "opencode": "^2.2.0"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/types/plugins/gh-pr-status/src/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/types/plugins/gh-pr-status/src/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/types/plugins/gh-pr-status/src/tui.d.ts",
      "import": "./dist/tui.js",
      "default": "./dist/tui.js"
    },
    "./rpc": {
      "types": "./dist/types/plugins/gh-pr-status/src/rpc.d.ts",
      "import": "./dist/rpc.js",
      "default": "./dist/rpc.js"
    },
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "dependencies": {
    "@opencode/plugin": "2.2.0",
    "@opencode/client": "2.2.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.7.0 <1",
    "@opentui/solid": ">=0.7.0 <1",
    "solid-js": ">=1.9.12 <2"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  }
}
